pe="button" class="btn btn-outline-secondary btn-xs text-danger rounded" data-remove-value>x</button> </div> </template> <template id="tpl-field"> <div class="border border-gray-200 p-3" data-field> <div class="flex flex-wrap items-end gap-3"> <div class="flex-1 min-w-[140px]"> <label class="block small fw-medium text-secondary mb-1">Label</label> <input class="form-control form-control-sm w-full" placeholder="Input Email" data-label /> </div> <div class="w-32"> <label class="block small fw-medium text-secondary mb-1">Key</label> <input class="form-control form-control-sm w-full" placeholder="email" data-key /> </div> <div class="w-32"> <label class="block small fw-medium text-secondary mb-1">Type</label> <select class="form-select form-select-sm w-full" data-type> <option value="text">Text</option> <option value="email">Email</option> <option value="password">Password</option> <option value="number">Number</option> <option value="textarea">Textarea</option> </select> </div> <div class="flex-1 min-w-[140px]"> <label class="block small fw-medium text-secondary mb-1">Placeholder</label> <input class="form-control form-control-sm w-full" placeholder="Optional hint text" data-placeholder /> </div> <div class="w-28"> <label class="block small fw-medium text-secondary mb-1">Sort Order</label> <input type="number" min="0" value="0" class="form-control form-control-sm w-full" data-sort /> </div> <label class="flex items-center gap-1 small text-secondary cursor-pointer pb-1"> <input type="checkbox" value="1" class="form-check-input" data-required checked /> Required </label> <button type="button" class="btn btn-outline-secondary btn-sm text-danger pb-1" data-remove-field>x Remove</button> </div> </div> </template> <script> document.addEventListener('DOMContentLoaded', function () { /* --- Helpers --- */ function nextIndex(prefix) { let max = -1; document.querySelectorAll('[name^="' + prefix + '["]').forEach(function (el) { const m = String(el.getAttribute('name') || '').match(new RegExp('^' + prefix.replace(/\[/g,'\\[').replace(/\]/g,'\\]') + '\\[(\\d+)\\]')); if (m) max = Math.max(max, parseInt(m[1], 10)); }); return max + 1; } function slugify(str) { return str.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); } const titleInput = document.getElementById('product-title'); const slugInput = document.getElementById('product-slug'); if (titleInput && slugInput) { const initialTitleSlug = slugify(titleInput.value).replace(/_/g, '-'); const currentSlug = String(slugInput.value || '').trim(); let manualSlug = currentSlug !== '' && currentSlug !== initialTitleSlug; function slugifyHyphen(str) { return slugify(str).replace(/_/g, '-'); } function syncProductSlug() { if (manualSlug) return; slugInput.value = slugifyHyphen(titleInput.value); } titleInput.addEventListener('input', syncProductSlug); titleInput.addEventListener('blur', syncProductSlug); slugInput.addEventListener('input', function () { const value = String(slugInput.value || '').trim(); if (value === '') { manualSlug = false; syncProductSlug(); return; } manualSlug = value !== slugifyHyphen(titleInput.value); }); } /* --- State --- */ let nextGroupIdx = nextIndex('option_groups'); let nextVariantIdx = nextIndex('variants'); let nextFieldIdx = nextIndex('form_fields'); const groupsWrap = document.getElementById('groups-wrap'); const variantsWrap = document.getElementById('variants-tbody') || document.querySelector('[data-variants]'); const fieldsWrap = document.getElementById('fields-wrap');

