                    { name: 'Package', key: 'package', mode: 'normal', values: ['Basic', 'Standard', 'Premium'] },
                    { name: 'Delivery Time', key: 'delivery_time', mode: 'normal', values: ['24 Hours', '2-3 Days', '7 Days'] }
                ]
            },
