                title: 'Custom',
                groups: [
                    { name: 'Variant Type', key: 'variant_type', mode: 'normal', values: ['Option 1', 'Option 2'] }
                ]
            }
        };

        function showAdminNotice(type, title, message) {
            if (window.createToast) {
                createToast(type, title, message);
            } else {
                alert(message || title);
            }
        }

        function buildPresetValue(gIdx, vIdx, label) {
            const frag = document.getElementById('tpl-option-value')?.content?.cloneNode(true);
            const el = frag?.querySelector('[data-value]');
            if (!el) return null;
            const value = slugify(label);
            const labelInput = el.querySelector('[data-label]');
            const valueInput = el.querySelector('[data-value-input]');
            const activeInput = el.querySelector('[data-active]');
            labelInput.setAttribute('name', 'option_groups[' + gIdx + '][values][' + vIdx + '][label]');
            labelInput.value = label;
            valueInput.setAttribute('name', 'option_groups[' + gIdx + '][values][' + vIdx + '][value]');
            valueInput.value = value;
            activeInput.setAttribute('name', 'option_groups[' + gIdx + '][values][' + vIdx + '][is_active]');
            const sortInput = document.createElement('input');
            sortInput.type = 'hidden';
            sortInput.name = 'option_groups[' + gIdx + '][values][' + vIdx + '][sort_order]';
            sortInput.value = String(vIdx);
            el.appendChild(sortInput);
            el.querySelector('[data-remove-value]')?.addEventListener('click', function () { el.remove(); });
            labelInput.addEventListener('blur', function () {
                if (valueInput && !valueInput.value.trim()) valueInput.value = slugify(this.value);
            });
            return el;
        }

        function buildPresetGroup(gIdx, group) {
            const frag = document.getElementById('tpl-option-group')?.content?.cloneNode(true);
            const gEl = frag?.querySelector('[data-group]');
            if (!gEl) return null;
            gEl.setAttribute('data-group-index', String(gIdx));
            const sortHid = document.createElement('input');
            sortHid.type = 'hidden';
            sortHid.name = 'option_groups[' + gIdx + '][sort_order]';
            sortHid.value = String(gIdx);
            gEl.prepend(sortHid);
            const nameInput = gEl.querySelector('[data-name]');
            const keyInput = gEl.querySelector('[data-key]');
            const modeInput = gEl.querySelector('[data-mode]');
            nameInput.setAttribute('name', 'option_groups[' + gIdx + '][name]');
            nameInput.value = group.name;
            keyInput.setAttribute('name', 'option_groups[' + gIdx + '][key]');
            keyInput.value = group.key;
            modeInput.setAttribute('name', 'option_groups[' + gIdx + '][mode]');
            modeInput.value = group.mode || 'normal';
            nameInput.addEventListener('blur', function () {
                if (keyInput && !keyInput.value.trim()) keyInput.value = slugify(this.value);
            });
            const valuesWrap = gEl.querySelector('[data-values]');
            group.values.forEach(function (label, vIdx) {
                const valueEl = buildPresetValue(gIdx, vIdx, label);
                if (valueEl) valuesWrap.appendChild(valueEl);
            });
            wireGroup(gEl);
            return gEl;
        }

        function clearVisibleVariantsForPreset() {
            document.querySelectorAll('[data-variants] [data-variant]').forEach(function (row) {
                const del = row.querySelector('[data-variant-delete]');
                if (del) {
                    del.value = '1';
                    row.classList.add('hidden');
                } else {
                    row.remove();
                }
            });
        }

        async function confirmPresetReplace(hasExisting) {
            if (!hasExisting) return true;
            const message = 'This preset will replace the option groups on this screen and rebuild the pricing rows. Save changes after reviewing prices.';
            if (window.digifyConfirm) {
                return await window.digifyConfirm({
                    title: 'Replace variants?',
                    message: message,
                    confirmText: 'Replace',
                    cancelText: 'Cancel',
                    tone: 'warning'
                });
            }
            return confirm(message);
        }

        async function applyVariantPreset(presetKey) {
            const preset = variantPresets[presetKey];
            if (!preset || !groupsWrap) return;
            const hasExisting = groupsWrap.querySelector('[data-group]') || document.querySelector('[data-variants] [data-variant]:not(.hidden)');
            if (!(await confirmPresetReplace(Boolean(hasExisting)))) return;
            document.querySelectorAll('#variant-presets [data-variant-preset]').forEach(function (btn) {
                btn.classList.toggle('is-active', btn.getAttribute('data-variant-preset') === presetKey);
            });
            groupsWrap.innerHTML = '';
            document.getElementById('groups-empty-state')?.classList.add('hidden');
            clearVisibleVariantsForPreset();
            preset.groups.forEach(function (group) {
                const gIdx = nextGroupIdx++;
                const groupEl = buildPresetGroup(gIdx, group);
                if (groupEl) groupsWrap.appendChild(groupEl);
            });
            const durationLabel = document.querySelector('[name="exclusive_duration_label"]');
            const accountLabel = document.querySelector('[name="exclusive_account_label"]');
            if (durationLabel) durationLabel.value = preset.groups[0]?.name || durationLabel.value;
            if (accountLabel) accountLabel.value = preset.groups[1]?.name || accountLabel.value;
            document.getElementById('btn-auto-generate')?.click();
            showAdminNotice('success', 'Preset applied', preset.title + ' variant setup is ready. Now adjust price, stock and labels as needed.');
        }

        document.querySelectorAll('#variant-presets [data-variant-preset]').forEach(function (btn) {
            btn.addEventListener('click', function () {
                applyVariantPreset(btn.getAttribute('data-variant-preset'));
            });
        }); /* --- Read current groups / values from DOM --- */ function readGroups() { const groups = []; document.querySelectorAll('#groups-wrap [data-group]').forEach(function (gEl) { const nameEl = gEl.querySelector('input[name$="[name]"]'); const keyEl = gEl.querySelector('input[name$="[key]"]'); const modeEl = gEl.querySelector('select[name$="[mode]"], select[data-mode]'); const name = (nameEl?.value || '').trim(); const key = (keyEl?.value || '').trim(); const mode = (modeEl?.value || 'normal').trim(); if (!name || !key) return; const values = []; gEl.querySelectorAll('[data-value]').forEach(function (vEl) { const labelEl = vEl.querySelector('input[data-label], input[name$="[label]"]'); const valueEl = vEl.querySelector('input[data-value-input], input[name$="[value]"]:not([type=hidden])'); const label = (labelEl?.value || '').trim(); const value = (valueEl?.value || '').trim(); if (label && value) values.push({ label, value }); }); groups.push({ name, key, mode: (mode === 'exclusive' ? 'exclusive' : 'normal'), values }); }); return groups; } /* --- Read existing variant combos --- */ function readExistingVariantCombos() { const combos = []; document.querySelectorAll('[data-variants] [data-variant]').forEach(function (row) { const del = row.querySelector('[data-variant-delete]'); if (del && del.value === '1') return; const combo = {}; row.querySelectorAll('select[name*="[options]["]').forEach(function (sel) { const m = sel.name.match(/\[options\]\[([^\]]+)\]/); if (m) combo[m[1]] = sel.value; }); combos.push(combo); }); return combos; } /* --- Cartesian product --- */ function cartesian(groups) { if (!groups.length) return []; const normal = groups.filter(function (g) { return g.mode !== 'exclusive'; }); const exclusive = groups.filter(function (g) { return g.mode === 'exclusive'; }); const normalCombos = normal.reduce(function (acc, group) { const next = []; acc.forEach(function (prev) { group.values.forEach(function (val) { next.push(Object.assign({}, prev, { [group.key]: { label: val.label, value: val.value } })); }); }); return next; }, [{}]); if (!exclusive.length) { return normalCombos; } const combos = []; exclusive.forEach(function (exGroup) { exGroup.values.forEach(function (val) { normalCombos.forEach(function (base) { combos.push(Object.assign({}, base, { [exGroup.key]: { label: val.label, value: val.value } })); }); }); }); return combos; } /* --- Build variant table header --- */ function ensureVariantTableVisible(groups) { const emptyState = document.getElementById('variants-empty-state'); const tableWrap = document.getElementById('variants-table-wrap'); const theadRow = document.getElementById('variants-thead-row'); const existingTable = document.getElementById('variants-table'); if (emptyState) emptyState.classList.add('hidden'); if (tableWrap && theadRow) { tableWrap.classList.remove('hidden'); theadRow.innerHTML = ''; groups.forEach(function (g) { const th = document.createElement('th'); th.className = 'pb-2 pr-3 fw-medium small text-secondary text-left'; th.textContent = g.name; theadRow.appendChild(th); }); ['Sale Price (Tk)', 'Regular Price (Tk)', 'Stock', 'Active', ''].forEach(function (label) { const th = document.createElement('th'); th.className = 'pb-2 pr-3 fw-medium small text-secondary text-left'; th.textContent = label; theadRow.appendChild(th); }); } } /* --- Build one variant row --- */ function buildVariantRow(vIdx, groups, preset) { preset = preset || {}; const tr = document.createElement('tr'); tr.className = 'border-b border-gray-50 hover:bg-gray-50 transition-colors'; tr.setAttribute('data-variant', ''); tr.setAttribute('data-variant-index', String(vIdx)); const hidDel = document.createElement('input'); hidDel.type = 'hidden'; hidDel.name = 'variants[' + vIdx + '][_delete]'; hidDel.value = '0'; hidDel.setAttribute('data-variant-delete', ''); tr.appendChild(hidDel); groups.forEach(function (g) { const td = document.createElement('td'); td.className = 'py-2 pr-3'; const sel = document.createElement('select'); sel.name = 'variants[' + vIdx + '][options][' + g.key + ']'; sel.className = 'form-select w-full h-11 min-w-[150px]'; const defOpt = document.createElement('option'); defOpt.value = ''; defOpt.textContent = '-- Select --'; sel.appendChild(defOpt); g.values.forEach(function (v) { const o = document.createElement('option'); o.value = v.value; o.textContent = v.label; if (preset[g.key] && preset[g.key] === v.value) o.selected = true; sel.appendChild(o); }); td.appendChild(sel); tr.appendChild(td); }); function numCell(fieldName, placeholder, width) { const td = document.createElement('td'); td.className = 'py-2 pr-3'; const inp = document.createElement('input'); inp.type = 'number'; inp.step = '0.01'; inp.min = '0'; inp.name = fieldName; inp.placeholder = placeholder; inp.value = preset[fieldName.replace(/variants\[\d+\]\[/, '').replace(']', '')] || ''; inp.className = 'form-control form-control-sm ' + width; td.appendChild(inp); tr.appendChild(td); return inp; } numCell('variants[' + vIdx + '][price]', '0.00', 'w-24'); numCell('variants[' + vIdx + '][regular_price]', 'MRP', 'w-24'); const tdStock = document.createElement('td'); tdStock.className = 'py-2 pr-3'; const stockInp = document.createElement('input'); stockInp.type = 'number'; stockInp.min = '0'; stockInp.name = 'variants[' + vIdx + '][stock]'; stockInp.placeholder = 'unlimited'; stockInp.value = preset.stock || ''; stockInp.className = 'form-control form-control-sm w-20 '; tdStock.appendChild(stockInp); tr.appendChild(tdStock); const tdActive = document.createElement('td'); tdActive.className = 'py-2 pr-3'; const chk = document.createElement('input'); chk.type = 'checkbox'; chk.name = 'variants[' + vIdx + '][is_active]'; chk.value = '1'; chk.className = 'form-check-input rounded'; chk.checked = true; tdActive.appendChild(chk); tr.appendChild(tdActive); const tdDel = document.createElement('td'); tdDel.className = 'py-2'; const delBtn = document.createElement('button'); delBtn.type = 'bu