w.createToast) { createToast('info', 'Info', 'All combinations already exist! You can adjust prices and stock for each row.'); } else { alert('All combinations already exist! You can adjust prices and stock for each row.'); } } }); /* --- Add Variant (manual) --- */ document.getElementById('btn-add-variant')?.addEventListener('click', function () { const groups = readGroups(); if (!groups.length) { window.createToast ? createToast('warning', 'Warning', 'Please add Option Groups first.') : alert('Please add Option Groups first.'); return; } ensureVariantTableVisible(groups); const tbody = document.getElementById('variants-tbody') || document.querySelector('[data-variants]'); if (!tbody) return; const row = buildVariantRow(nextVariantIdx++, groups, {}); tbody.appendChild(row); }); /* --- Wire existing variant remove buttons --- */ document.querySelectorAll('[data-remove-variant]').forEach(function (btn) { btn.addEventListener('click', function () { const row = btn.closest('[data-variant]'); if (!row) return; const idInput = row.querySelector('input[name*="[id]"]'); const delInput = row.querySelector('[data-variant-delete]'); if (idInput && delInput) { delInput.value = '1'; row.style.opacity = '0.4'; row.style.textDecoration = 'line-through'; } else row.remove(); }); }); /* --- Option Groups --- */ function wireGroup(groupEl) { const gIndex = parseInt(groupEl.getAttribute('data-group-index') || '0', 10); const valuesWrap = groupEl.querySelector('[data-values]'); const tplValue = document.getElementById('tpl-option-value'); groupEl.querySelector('[data-remove-group]')?.addEventListener('click', function () { groupEl.remove(); }); function nextValIdx() { let max = -1; groupEl.querySelectorAll('[name^="option_groups[' + gIndex + '][values]["]').forEach(function (el) { const m = el.name.match(/\[values\]\[(\d+)\]/); if (m) max = Math.max(max, parseInt(m[1], 10)); }); return max + 1; } groupEl.querySelector('[data-add-value]')?.addEventListener('click', function () { const 