rag) return; const gEl = frag.querySelector('[data-group]'); if (!gEl) return; gEl.setAttribute('data-group-index', String(gIdx)); const sortHid = document.createElement('input'); sortHid.type = 'hidden'; sortHid.name = 'option_groups[' + gIdx + '][sort_order]'; sortHid.value = String(gIdx); gEl.prepend(sortHid); gEl.querySelector('[data-name]').setAttribute('name', 'option_groups[' + gIdx + '][name]'); gEl.querySelector('[data-key]').setAttribute('name', 'option_groups[' + gIdx + '][key]'); gEl.querySelector('[data-mode]')?.setAttribute('name', 'option_groups[' + gIdx + '][mode]'); /* Auto-fill key from name */ gEl.querySelector('[data-name]')?.addEventListener('blur', function () { const keyInput = gEl.querySelector('[data-key]'); if (keyInput && !keyInput.value.trim()) keyInput.value = slugify(this.value); }); wireGroup(gEl); const emptyState = document.getElementById('groups-empty-state'); if (emptyState) emptyState.classList.add('hidden'); groupsWrap?.appendChild(frag); }); /* --- Form Fields --- */ function wireField(fieldEl) { fieldEl.querySelector('[data-remove-field]')?.addEventListener('click', function () { fieldEl.remove(); }); fieldEl.querySelector('[data-label]')?.addEventListener('blur', function () { const keyInput = fieldEl.querySelector('[data-key]'); if (keyInput && !keyInput.value.trim()) keyInput.value = slugify(this.value); }); } document.querySelectorAll('#fields-wrap [data-field]').forEach(wireField); document.getElementById('btn-add-field')?.addEventListener('click', function () { const fIdx = nextFieldIdx++; const frag = document.getElementById('tpl-field')?.content?.cloneNode(true); if (!frag) return; const el = frag.querySelector('[data-field]'); if (!el) return; el.setAttribute('data-field-index', String(fIdx)); el.querySelector('[data-label]').setAttribute('name', 'form_fields[' + fIdx + '][label]'); el.querySelector('[data-key]').setAttribute('name', 'form_fields[' + fIdx + '][key]'); el.querySelector('[data-type]').setAttribute('name'